/** URL for a placeholder photo, or null so the UI falls back to the brand placeholder. */
export function img(key: string, width: 500 | 960 = 500): string | null {
  const u = IMAGES[key];
  return u ? u.replace('/960px-', `/${width}px-`) : null;
}

export const imageKeys = Object.keys(IMAGES);
